'use strict';

// MODULES //

var tape = require( 'tape' );
var hasOwnProp = require( '@stdlib/assert/has-own-property' );
var isFunction = require( '@stdlib/assert/is-function' );
var isInt64 = require( '@stdlib/assert/is-int64' );
var isEqual = require( '@stdlib/number/int64/base/assert/is-equal' );
var Number = require( '@stdlib/number/ctor' );
var Int64 = require( '@stdlib/number/int64/ctor' );
var Int64Array = require( './../lib' );


// FUNCTIONS //

/**
* Adds two 64-bit signed integers.
*
* @private
* @param {Int64} x - first value
* @param {Int64} y - second value
* @returns {Int64} sum
*/
function add( x, y ) {
	return new Int64( Number( x ) + Number( y ) );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof Int64Array, 'function', 'main export is a function' );
	t.end();
});

tape( 'attached to the prototype of the main export is a `reduceRight` method', function test( t ) {
	t.strictEqual( hasOwnProp( Int64Array.prototype, 'reduceRight' ), true, 'has property' );
	t.strictEqual( isFunction( Int64Array.prototype.reduceRight ), true, 'has method' );
	t.end();
});

tape( 'the method throws an error if invoked with a `this` context which is not a 64-bit signed integer array instance', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Int64Array( 5 );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.reduceRight.call( value, add );
		};
	}
});

tape( 'the method throws an error if provided a first argument which is not a function', function test( t ) {
	var values;
	var arr;
	var i;

	arr = new Int64Array( 5 );

	values = [
		'5',
		5,
		NaN,
		true,
		false,
		null,
		void 0,
		{},
		[]
	];
	for ( i = 0; i < values.length; i++ ) {
		t.throws( badValue( values[i] ), TypeError, 'throws an error when provided '+values[i] );
	}
	t.end();

	function badValue( value ) {
		return function badValue() {
			return arr.reduceRight( value );
		};
	}
});

tape( 'the method throws an error if not provided an initial value when operating on an empty 64-bit signed integer array', function test( t ) {
	var arr;

	arr = new Int64Array( 0 );
	t.throws( foo, Error, 'throws an error' );
	t.end();

	function foo() {
		arr.reduceRight( add );
	}
});

tape( 'the method uses the last element of the array as the initial value when an initial value is not provided', function test( t ) {
	var valueArray;
	var accArray;
	var expected;
	var actual;
	var arr;
	var len;

	arr = new Int64Array( [ -1, 2, 3 ] );
	len = arr.length;
	accArray = [ 3, 5 ];
	valueArray = [ 2, -1 ];
	expected = new Int64( 4 );
	actual = arr.reduceRight( reducer );

	t.strictEqual( isInt64( actual ), true, 'returns expected value' );
	t.strictEqual( isEqual( actual, expected ), true, 'returns expected value' );

	t.end();

	function reducer( acc, value, index ) {
		var ind = len - index - 2;
		t.strictEqual( isInt64( acc ), true, 'returns expected value' );
		t.strictEqual( isEqual( acc, new Int64( accArray[ ind ] ) ), true, 'returns expected value' );
		t.strictEqual( isInt64( value ), true, 'returns expected value' );
		t.strictEqual( isEqual( value, new Int64( valueArray[ ind ] ) ), true, 'returns expected value' );
		return add( acc, value );
	}
});

tape( 'the method supports providing an initial value as the second argument', function test( t ) {
	var valueArray;
	var accArray;
	var expected;
	var actual;
	var arr;
	var len;

	arr = new Int64Array( [ -1, 2, 3 ] );
	len = arr.length;
	accArray = [ 2, 5, 7 ];
	valueArray = [ 3, 2, -1 ];
	expected = new Int64( 6 );
	actual = arr.reduceRight( reducer, new Int64( 2 ) );

	t.strictEqual( isInt64( actual ), true, 'returns expected value' );
	t.strictEqual( isEqual( actual, expected ), true, 'returns expected value' );

	t.end();

	function reducer( acc, value, index ) {
		var ind = len - index - 1;
		t.strictEqual( isInt64( acc ), true, 'returns expected value' );
		t.strictEqual( isEqual( acc, new Int64( accArray[ ind ] ) ), true, 'returns expected value' );
		t.strictEqual( isInt64( value ), true, 'returns expected value' );
		t.strictEqual( isEqual( value, new Int64( valueArray[ ind ] ) ), true, 'returns expected value' );
		return add( acc, value );
	}
});

tape( 'the method returns the accumulated result', function test( t ) {
	var expected;
	var actual;
	var arr;

	arr = new Int64Array( [ -1, 2, 3 ] );
	expected = new Int64( 4 );
	actual = arr.reduceRight( add );

	t.strictEqual( isInt64( actual ), true, 'returns expected value' );
	t.strictEqual( isEqual( actual, expected ), true, 'returns expected value' );
	t.end();
});

tape( 'the method supports returning real-valued results', function test( t ) {
	var expected;
	var actual;
	var arr;

	arr = new Int64Array( [ -1, 2, 3 ] );
	expected = 4;
	actual = arr.reduceRight( reducer, 0 );

	t.strictEqual( actual, expected, 'returns expected value' );
	t.end();

	function reducer( acc, value ) {
		return acc + Number( value );
	}
});
